#!/usr/bin/env node
//
// Print the generated user-docs pages as PDFs: the same markdown GitHub shows, in the print sheet
// (print.css, the booklets' look), every page stamped with the app version, commit and date.
//
//     pixi run doc-pdf [-- --only training] [--out DIR] [--html]
//
// The pages are the user-docs pages with a shot set (user-docs/shots → `ShotSet.page`, a `.md`), each
// generated by frontend/src/utils/*Doc.ts through utils/docPage.ts. Nothing is typed here: refresh the
// page (its vitest -u) and the images (doc-shots, doc-images) first, then print. A label the page bolds
// mid-sentence (`Open **Manage images**`) prints as the app's label chip; a bold lead-in that opens a
// paragraph or list item (`**Do:**`) stays bold. GitHub's `> [!NOTE]` / `> [!WARNING]` print as notes.
//
// Output (default `docshots-out/pdf/`, git-ignored): <page>.pdf, plus <page>.html with --html. Not
// committed: a PDF is a printout of a version of the app, and the stamp says which.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { basename, join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
import { chromium, commit, findChromium, repo } from '../lib/chromium.mjs'

const docs = join(repo, 'user-docs')
const { SHOT_SETS } = await import(pathToFileURL(join(docs, 'shots', 'index.ts')).href)
const { marked } = createRequire(join(repo, 'frontend', 'package.json'))('marked')

function parseArgs(argv) {
  const a = { out: join(repo, 'docshots-out', 'pdf'), only: '', html: false }
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i]
    if (k === '--html') a.html = true
    else if (k === '--out') a.out = resolve(argv[++i])
    else if (k === '--only') a.only = argv[++i]
    else throw new Error(`unknown argument ${k}`)
  }
  return a
}

// The app version as tools outside Julia read it: frontend/package.json, kept in step with
// app/Project.toml by a testset (app/src/config.jl → cecelia_version).
function stamp() {
  const { version } = JSON.parse(readFileSync(join(repo, 'frontend', 'package.json'), 'utf-8'))
  return { version: version ?? '?', commit: commit(), date: new Date().toISOString().slice(0, 10) }
}

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** A page's markdown as print HTML: notes, label chips, numbered step headings. */
export function printHtml(md) {
  const src = md.replace(/^<!--.*?-->\n/s, '')
    // GitHub alerts → a note block (marked has no alerts); the note's lines stay one paragraph
    .replace(/^> \[!(NOTE|WARNING)\]\n((?:> .*\n?)+)/gm, (_, kind, body) =>
      `<div class="note ${kind.toLowerCase()}">\n\n${body.replace(/^> /gm, '')}\n</div>\n`)
  let html = marked.parse(src, { gfm: true })
  // a bold that does NOT open its paragraph or list item is an app label → chip
  html = html.replace(/(<(?:p|li|td)>)?<strong>([^<]+)<\/strong>/g, (m, open, text) => open ? m : `<b class="ui">${text}</b>`)
  // "### 3. Segment" → a numbered step heading
  html = html.replace(/<h3>(\d+)\. /g, '<h3><span class="n">$1</span> ')
  // each section and step (a heading up to the next one) prints whole when it fits on a page, so a
  // heading never strands at a page's foot and a step's screenshot stays with its words
  return html.split(/(?=<h[23][ >])/).map(b => (/^<h[23][ >]/.test(b) ? `<section>${b}</section>` : b)).join('')
}

const a = parseArgs(process.argv.slice(2))
const pages = SHOT_SETS.map(s => s.page).filter(p => p.endsWith('.md') && !p.includes('/'))
const todo = a.only ? pages.filter(p => basename(p, '.md') === a.only) : pages
if (a.only && !todo.length) throw new Error(`no user-docs page "${a.only}" (pages: ${pages.join(', ')})`)
const css = readFileSync(join(repo, 'scripts', 'docshots', 'print.css'), 'utf-8')
const st = stamp()
mkdirSync(a.out, { recursive: true })

const browser = await chromium.launch({ executablePath: findChromium(), headless: true })
try {
  for (const page of todo) {
    const md = readFileSync(join(docs, page), 'utf-8')
    const title = md.match(/^# (.+)$/m)?.[1] ?? page
    const body = printHtml(md)
    const missing = [...body.matchAll(/<img src="([^"]+)"/g)].map(m => m[1]).filter(f => !existsSync(join(docs, f)))
    if (missing.length) throw new Error(`${page}: images not composed: ${missing.join(', ')} (pixi run doc-shots, then doc-images)`)
    const html = `<!doctype html><html><head><meta charset="utf-8"><base href="${pathToFileURL(docs).href}/">
<title>${esc(title)}</title><style>${css}</style></head><body>${body}</body></html>`
    // a file:// page, so the composed images load from user-docs/images
    const file = join(a.out, `${basename(page, '.md')}.html`)
    writeFileSync(file, html, 'utf-8')
    const pg = await browser.newPage()
    await pg.goto(pathToFileURL(file).href, { waitUntil: 'load' })
    const foot = `<div style="font: 7pt system-ui, sans-serif; color: #635d57; width: 100%; padding: 0 14mm;
      display: flex; justify-content: space-between;"><span>Cecelia ${esc(st.version)} · ${esc(st.commit)} · ${esc(st.date)}</span>
      <span>${esc(title)} · <span class="pageNumber"></span>/<span class="totalPages"></span></span></div>`
    const out = join(a.out, `${basename(page, '.md')}.pdf`)
    await pg.pdf({
      path: out, format: 'A4', printBackground: true,
      displayHeaderFooter: true, headerTemplate: '<span></span>', footerTemplate: foot,
      margin: { top: '14mm', bottom: '16mm', left: '14mm', right: '14mm' },
    })
    await pg.close()
    if (!a.html) (await import('node:fs')).rmSync(file)
    console.log(`✓ ${page} → ${out}`)
  }
} finally {
  await browser.close()
}
